	midpoint := time.Now()
	time.Sleep(10 * time.Millisecond)
	rec.RecordBuild(1000000, []string{}, 0, "second")

	builds := rec.GetBuildsSince(midpoint)

	if len(builds) != 1 {
		t.Errorf("expected 1 build since midpoint, got %d", len(builds))
