     1→// Package optimizer implements adaptive optimization rules
     2→package optimizer
     3→
     4→import (
     5→	"github.com/user/freelang-evolving-compiler/internal/ast"
     6→	"github.com/user/freelang-evolving-compiler/internal/profiler"
