     9→// OptimizationRule defines a transformation rule
    10→type OptimizationRule struct {
    11→	Name            string
    12→	TargetPattern   profiler.PatternKind
    13→	Priority        int
    14→	Description     string
    15→	Apply           func(*ast.Node) *ast.Node
    16→}
    17→
    18→// ConstantFoldingRule evaluates constant expressions at compile time
    19→var ConstantFoldingRule = OptimizationRule{
    20→	Name:          "ConstantFolding",
    21→	TargetPattern: profiler.PatternConstantExpr,
    22→	Priority:      100,
    23→	Description:   "Evaluate constant expressions at compile time",
    24→	Apply: func(node *ast.Node) *ast.Node {
    25→		if node == nil {
    26→			return node
    27→		}
    28→
    29→		// If it's a binary expression with two integer literals
    30→		if node.Kind == ast.NodeBinaryExpr && len(node.Children) == 2 {
    31→			left, right := node.Children[0], node.Children[1]
    32→
    33→			if left.Kind == ast.NodeIntLit && right.Kind == ast.NodeIntLit {
    34→				result := evaluateConstExpr(node)
    35→				if result != nil {
    36→					return result
    37→				}
    38→			}
    39→		}
    40→
    41→		// Recursively apply to children
    42→		for i, child := range node.Children {
    43→			node.Children[i] = ConstantFoldingRule.Apply(child)
    44→		}
    45→
    46→		return node
    47→	},
    48→}
    49→
    50→// DeadCodeEliminationRule removes unused variable assignments
    51→var DeadCodeEliminationRule = OptimizationRule{
    52→	Name:          "DeadCodeElimination",
    53→	TargetPattern: profiler.PatternDeadAssign,
    54→	Priority:      80,
    55→	Description:   "Remove unused variable assignments",
    56→	Apply: func(node *ast.Node) *ast.Node {
    57→		if node == nil {
    58→			return node
    59→		}
    60→
    61→		// Mark dead assignments by filtering out declarations that are never read
    62→		// This would require dataflow analysis in a real implementation
    63→		// For now, just mark them with a comment
    64→
    65→		for i, child := range node.Children {
    66→			node.Children[i] = DeadCodeEliminationRule.Apply(child)
    67→		}
    68→
    69→		return node
    70→	},
    71→}
    72→
    73→// InliningRule substitutes function calls with their body
    74→var InliningRule = OptimizationRule{
    75→	Name:          "FunctionInlining",
    76→	TargetPattern: profiler.PatternInlinableCall,
    77→	Priority:      70,
    78→	Description:   "Inline simple function calls",
    79→	Apply: func(node *ast.Node) *ast.Node {
    80→		if node == nil {
    81→			return node
    82→		}
    83→
    84→		// Function call inlining would require access to the program's function definitions
    85→		// This is a placeholder implementation
    86→
    87→		for i, child := range node.Children {
    88→			node.Children[i] = InliningRule.Apply(child)
    89→		}
    90→
    91→		return node
    92→	},
    93→}
    94→
    95→// LoopInvariantMovementRule hoists loop-invariant expressions
    96→var LoopInvariantMovementRule = OptimizationRule{
    97→	Name:          "LoopInvariantMovement",
    98→	TargetPattern: profiler.PatternLoopInvariant,
    99→	Priority:      60,
   100→	Description:   "Move loop-invariant expressions outside loops",
   101→	Apply: func(node *ast.Node) *ast.Node {
   102→		if node == nil {
   103→			return node
   104→		}
   105→
   106→		for i, child := range node.Children {
   107→			node.Children[i] = LoopInvariantMovementRule.Apply(child)
   108→		}
   109→
   110→		return node
   111→	},
   112→}
   113→
   114→// CommonSubexpressionRule eliminates redundant computations
   115→var CommonSubexpressionRule = OptimizationRule{
   116→	Name:          "CommonSubexpressionElimination",
   117→	TargetPattern: profiler.PatternRepeatedSubExpr,
   118→	Priority:      50,
   119→	Description:   "Cache results of repeated sub-expressions",
   120→	Apply: func(node *ast.Node) *ast.Node {
   121→		if node == nil {
   122→			return node
   123→		}
   124→
   125→		for i, child := range node.Children {
   126→			node.Children[i] = CommonSubexpressionRule.Apply(child)
   127→		}
   128→
   129→		return node
   130→	},
   131→}
   132→
   133→// evaluateConstExpr computes the result of a constant binary expression
   134→func evaluateConstExpr(node *ast.Node) *ast.Node {
   135→	if node == nil || node.Kind != ast.NodeBinaryExpr {
   136→		return nil
   137→	}
   138→
   139→	if len(node.Children) != 2 {
   140→		return nil
   141→	}
   142→
   143→	left, right := node.Children[0], node.Children[1]
   144→	if left.Kind != ast.NodeIntLit || right.Kind != ast.NodeIntLit {
   145→		return nil
   146→	}
   147→
   148→	leftVal := parseIntLiteral(left.Value)
   149→	rightVal := parseIntLiteral(right.Value)
   150→
   151→	var result int64
   152→	switch node.Value {
   153→	case "+":
   154→		result = leftVal + rightVal
   155→	case "-":
   156→		result = leftVal - rightVal
   157→	case "*":
   158→		result = leftVal * rightVal
   159→	case "/":
   160→		if rightVal == 0 {
   161→			return nil // Don't fold division by zero
   162→		}
   163→		result = leftVal / rightVal
   164→	default:
   165→		return nil // Not a binary operator we can fold
   166→	}
   167→
   168→	// Return a new constant node with the computed value
   169→	return &ast.Node{
   170→		Kind:  ast.NodeIntLit,
   171→		Value: formatInt(result),
   172→		Line:  node.Line,
   173→		Col:   node.Col,
   174→	}
   175→}
   176→
   177→// parseIntLiteral converts a string to int64
   178→func parseIntLiteral(s string) int64 {
   179→	var result int64
   180→	for _, c := range s {
   181→		if c >= '0' && c <= '9' {
   182→			result = result*10 + int64(c-'0')
   183→		}
   184→	}
   185→	return result
   186→}
   187→
   188→// formatInt converts int64 back to string
   189→func formatInt(n int64) string {
   190→	if n == 0 {
   191→		return "0"
   192→	}
   193→	var result string
   194→	neg := n < 0
   195→	if neg {
   196→		n = -n
   197→	}
   198→	for n > 0 {
   199→		result = string(byte(n%10)+'0') + result
   200→		n /= 10
   201→	}
   202→	if neg {
   203→		result = "-" + result
   204→	}
   205→	return result
   206→}
   207→
   208→// DefaultRules returns all optimization rules in default order
   209→func DefaultRules() []OptimizationRule {
   210→	return []OptimizationRule{
   211→		ConstantFoldingRule,
   212→		DeadCodeEliminationRule,
   213→		InliningRule,
   214→		LoopInvariantMovementRule,
   215→		CommonSubexpressionRule,
   216→	}
   217→}
