     9→// EvolutionMetrics captures a single build's metrics
    10→type EvolutionMetrics struct {
    11→	BuildID      string
    12→	Timestamp    time.Time
    13→	BuildTimeNs  int64
    14→	OptsPassed   int    // number of optimization rules that modified code
    15→	OptsApplied  []string
    16→	CodeSizeBy   int // output code size in bytes
    17→	SourceHash   string
    18→}
    19→
    20→// EvolutionRecorder accumulates build metrics over time
    21→type EvolutionRecorder struct {
    22→	metrics []EvolutionMetrics
    23→	startID int
    24→}
    25→
    26→// NewEvolutionRecorder creates a new recorder
    27→func NewEvolutionRecorder() *EvolutionRecorder {
    28→	return &EvolutionRecorder{
    29→		metrics: make([]EvolutionMetrics, 0),
    30→		startID: 1,
    31→	}
    32→}
    33→
    34→// RecordBuild adds a new build record
    35→func (er *EvolutionRecorder) RecordBuild(buildTime int64, optsApplied []string,
    36→	codeSize int, sourceHash string) EvolutionMetrics {
    37→
    38→	metric := EvolutionMetrics{
    39→		BuildID:     fmt.Sprintf("build_%d", len(er.metrics)+er.startID),
    40→		Timestamp:   time.Now(),
    41→		BuildTimeNs: buildTime,
    42→		OptsPassed:  len(optsApplied),
    43→		OptsApplied: optsApplied,
    44→		CodeSizeBy:  codeSize,
    45→		SourceHash:  sourceHash,
    46→	}
    47→
    48→	er.metrics = append(er.metrics, metric)
    49→	return metric
    50→}
    51→
    52→// GetMetrics returns all recorded metrics
    53→func (er *EvolutionRecorder) GetMetrics() []EvolutionMetrics {
    54→	return er.metrics
    55→}
    56→
    57→// GetLastBuild returns the most recent build, or nil if none recorded
    58→func (er *EvolutionRecorder) GetLastBuild() *EvolutionMetrics {
    59→	if len(er.metrics) == 0 {
    60→		return nil
    61→	}
    62→	m := er.metrics[len(er.metrics)-1]
    63→	return &m
    64→}
    65→
    66→// GetBuildCount returns the number of recorded builds
    67→func (er *EvolutionRecorder) GetBuildCount() int {
    68→	return len(er.metrics)
    69→}
    70→
    71→// AverageBuildTime returns mean build duration in nanoseconds
    72→func (er *EvolutionRecorder) AverageBuildTime() int64 {
    73→	if len(er.metrics) == 0 {
    74→		return 0
    75→	}
    76→
    77→	total := int64(0)
    78→	for _, m := range er.metrics {
    79→		total += m.BuildTimeNs
    80→	}
    81→	return total / int64(len(er.metrics))
    82→}
    83→
    84→// AverageOptimizationsApplied returns mean number of optimizations per build
    85→func (er *EvolutionRecorder) AverageOptimizationsApplied() float64 {
    86→	if len(er.metrics) == 0 {
    87→		return 0
    88→	}
    89→
    90→	total := 0
    91→	for _, m := range er.metrics {
    92→		total += m.OptsPassed
    93→	}
    94→	return float64(total) / float64(len(er.metrics))
    95→}
    96→
    97→// GetOptimizationFrequency returns how many times each optimization was applied
    98→func (er *EvolutionRecorder) GetOptimizationFrequency() map[string]int {
    99→	freq := make(map[string]int)
   100→	for _, m := range er.metrics {
