     1→// Package profiler implements AST pattern collection and analysis
     2→package profiler
     3→
     4→import (
     5→	"time"
     6→
     7→	"github.com/user/freelang-evolving-compiler/internal/ast"
     8→)
     9→
    10→// Collector accumulates pattern statistics during AST analysis
    11→type Collector struct {
    12→	patterns         map[string]*Pattern // key: signature, value: Pattern
    13→	startTime        time.Time
    14→	buildTimeNs      int64
    15→	totalConstExprs  int64
    16→	totalDeadAssigns int64
    17→	totalInlCalls    int64
    18→}
    19→
    20→// NewCollector creates a new pattern collector
    21→func NewCollector() *Collector {
    22→	return &Collector{
    23→		patterns:  make(map[string]*Pattern),
    24→		startTime: time.Now(),
    25→	}
    26→}
    27→
    28→// CollectFromAST traverses the AST and collects all patterns
    29→func (c *Collector) CollectFromAST(program *ast.Node) {
    30→	if program == nil {
    31→		return
    32→	}
    33→
    34→	ctx := NewPatternContext(program)
    35→	ctx.AnalyzeNode(program)
    36→
    37→	// Collect constant expressions
    38→	constExprs := ctx.FindConstantExprs(program)
    39→	for _, p := range constExprs {
    40→		c.recordPattern(p.Signature, PatternConstantExpr, 100000) // 100us saved per const eval
    41→		c.totalConstExprs++
    42→	}
    43→
    44→	// Collect dead assigns
    45→	deadAssigns := ctx.DetectDeadAssigns()
    46→	for _, varName := range deadAssigns {
    47→		sig := "DeadAssign:" + varName
    48→		c.recordPattern(sig, PatternDeadAssign, 10000) // 10us saved per unused var
    49→		c.totalDeadAssigns++
    50→	}
    51→
    52→	// Collect inlinable calls
    53→	for fnName, callCount := range ctx.FunctionCalls {
    54→		if fnDef, ok := findFunctionDef(fnName, program); ok {
    55→			if isFunctionInlinable(fnDef) {
    56→				sig := "CallExpr:" + fnName
    57→				c.recordPattern(sig, PatternInlinableCall, int64(callCount)*50000) // 50us per inline call
    58→				c.totalInlCalls++
    59→			}
    60→		}
    61→	}
    62→
    63→	// Collect repeated expressions (optimization candidate)
    64→	topExprs := ctx.TopPatterns(10)
    65→	for _, expr := range topExprs {
    66→		if expr.Count > 1 {
    67→			c.recordPattern(expr.Signature, PatternRepeatedSubExpr, expr.Count*1000)
    68→		}
    69→	}
    70→
    71→	c.buildTimeNs = time.Since(c.startTime).Nanoseconds()
    72→}
    73→
    74→// recordPattern updates or creates a pattern entry
    75→func (c *Collector) recordPattern(sig string, kind PatternKind, savedNs int64) {
    76→	if p, exists := c.patterns[sig]; exists {
    77→		p.Count++
    78→		p.SavedNs += savedNs
    79→	} else {
    80→		c.patterns[sig] = &Pattern{
    81→			Kind:      kind,
    82→			Signature: sig,
    83→			Count:     1,
    84→			SavedNs:   savedNs,
    85→		}
    86→	}
    87→}
    88→
    89→// GetPatterns returns all collected patterns
    90→func (c *Collector) GetPatterns() []Pattern {
    91→	patterns := make([]Pattern, 0, len(c.patterns))
    92→	for _, p := range c.patterns {
    93→		patterns = append(patterns, *p)
    94→	}
    95→	return patterns
    96→}
    97→
    98→// GetBuildTimeNs returns the build duration in nanoseconds
    99→func (c *Collector) GetBuildTimeNs() int64 {
   100→	return c.buildTimeNs
   101→}
   102→
   103→// GetTopPatterns returns the top N patterns by count
   104→func (c *Collector) GetTopPatterns(n int) []Pattern {
   105→	patterns := c.GetPatterns()
   106→
   107→	// Sort by count descending
   108→	for i := 0; i < len(patterns)-1; i++ {
   109→		for j := i + 1; j < len(patterns); j++ {
   110→			if patterns[j].Count > patterns[i].Count {
   111→				patterns[i], patterns[j] = patterns[j], patterns[i]
   112→			}
   113→		}
   114→	}
   115→
   116→	if n > len(patterns) {
   117→		n = len(patterns)
   118→	}
   119→	return patterns[:n]
   120→}
   121→
   122→// isFunctionInlinable checks if a function is simple enough to inline
   123→func isFunctionInlinable(fnDef *ast.Node) bool {
   124→	if fnDef == nil || fnDef.Kind != ast.NodeFnDecl {
   125→		return false
   126→	}
   127→
   128→	// Function is inlinable if its body is simple (single return, or short block)
   129→	if len(fnDef.Children) == 0 {
   130→		return false
   131→	}
   132→
   133→	body := fnDef.Children[len(fnDef.Children)-1]
   134→	if body == nil {
   135→		return false
   136→	}
   137→
   138→	// Single return statement is inlinable
   139→	if body.Kind == ast.NodeReturn {
   140→		return true
   141→	}
   142→
   143→	// Block with single statement is inlinable
   144→	if body.Kind == ast.NodeBlockStmt {
   145→		return len(body.Children) <= 1
   146→	}
   147→
   148→	return false
   149→}
   150→
   151→// Summary returns a text summary of collected patterns
   152→func (c *Collector) Summary() string {
   153→	total := len(c.patterns)
   154→	return "Collected " + string(rune(total)) + " unique patterns in " +
   155→		formatNs(c.buildTimeNs)
   156→}
   157→
   158→// formatNs formats nanoseconds as human-readable duration
   159→func formatNs(ns int64) string {
   160→	if ns < 1000 {
   161→		return string(rune(ns)) + "ns"
   162→	}
   163→	if ns < 1000000 {
   164→		return string(rune(ns/1000)) + "us"
   165→	}
   166→	if ns < 1000000000 {
   167→		return string(rune(ns/1000000)) + "ms"
   168→	}
   169→	return string(rune(ns/1000000000)) + "s"
   170→}
   171→

