     1→// Package profiler implements pattern detection and frequency tracking
     2→package profiler
     3→
     4→import (
     5→	"fmt"
     6→	"hash/fnv"
     7→	"strings"
     8→
     9→	"github.com/user/freelang-evolving-compiler/internal/ast"
    10→)
    11→
    12→// PatternKind identifies the type of pattern
    13→type PatternKind int
    14→
    15→const (
    16→	PatternConstantExpr PatternKind = iota
    17→	PatternDeadAssign
    18→	PatternInlinableCall
    19→	PatternLoopInvariant
    20→	PatternRepeatedSubExpr
    21→)
    22→
    23→func (pk PatternKind) String() string {
    24→	switch pk {
    25→	case PatternConstantExpr:
    26→		return "ConstantExpr"
    27→	case PatternDeadAssign:
    28→		return "DeadAssign"
    29→	case PatternInlinableCall:
    30→		return "InlinableCall"
    31→	case PatternLoopInvariant:
    32→		return "LoopInvariant"
    33→	case PatternRepeatedSubExpr:
    34→		return "RepeatedSubExpr"
    35→	default:
    36→		return "Unknown"
    37→	}
    38→}
    39→
    40→// Pattern represents a detected pattern with frequency and optimization benefit
    41→type Pattern struct {
    42→	Kind      PatternKind `json:"kind"`
    43→	Signature string      `json:"signature"`
    44→	Count     int64       `json:"count"`
    45→	SavedNs   int64       `json:"saved_ns"`
    46→}
    47→
    48→// PatternSignature generates a unique identifier for an AST node
    49→func PatternSignature(node *ast.Node) string {
    50→	if node == nil {
    51→		return "nil"
    52→	}
    53→
    54→	h := fnv.New64a()
    55→	h.Write([]byte(nodeKindStr(node.Kind)))
    56→
    57→	if node.Value != "" {
    58→		h.Write([]byte("|"))
    59→		h.Write([]byte(node.Value))
    60→	}
    61→
    62→	for _, child := range node.Children {
    63→		h.Write([]byte("|"))
    64→		h.Write([]byte(PatternSignature(child)))
    65→	}
    66→
    67→	return fmt.Sprintf("%x", h.Sum64())
    68→}
    69→
    70→// PatternType determines what kind of pattern this node represents
    71→func PatternType(node *ast.Node, context *PatternContext) PatternKind {
    72→	if node == nil {
    73→		return 0
    74→	}
    75→
    76→	// Constant expression: both operands are literals
    77→	if node.Kind == ast.NodeBinaryExpr && len(node.Children) == 2 {
    78→		left, right := node.Children[0], node.Children[1]
    79→		if isLiteral(left) && isLiteral(right) {
    80→			return PatternConstantExpr
    81→		}
    82→	}
    83→
    84→	// Inlinable call: function body is simple (single expression)
    85→	if node.Kind == ast.NodeCallExpr {
    86→		if fnName, ok := findFunctionDef(node.Value, context.Program); ok {
    87→			if fnName.Kind == ast.NodeFnDecl && len(fnName.Children) > 0 {
    88→				body := fnName.Children[len(fnName.Children)-1]
    89→				if body.Kind == ast.NodeBlockStmt && len(body.Children) <= 1 {
    90→					return PatternInlinableCall
    91→				}
    92→			}
    93→		}
    94→	}
    95→
    96→	return 0
    97→}
    98→
    99→// isLiteral checks if node is a literal (int, bool, string)
   100→func isLiteral(node *ast.Node) bool {
   101→	if node == nil {
   102→		return false
   103→	}
   104→	return node.Kind == ast.NodeIntLit
   105→}
   106→
   107→// PatternContext holds information for pattern analysis
   108→type PatternContext struct {
   109→	Program           *ast.Node
   110→	VariableUsage     map[string]int    // usage count per variable
   111→	InLoop            bool              // whether we're inside a loop
   112→	LoopInvariants    map[string]bool   // expressions that don't depend on loop var
   113→	RepeatedExprs     map[string]int    // frequency of sub-expressions
   114→	FunctionCalls     map[string]int    // frequency of function calls
   115→	AssignedVars      map[string]bool   // variables that are assigned
   116→	ReadVars          map[string]bool   // variables that are read
   117→}
   118→
   119→// NewPatternContext creates a new pattern analysis context
   120→func NewPatternContext(program *ast.Node) *PatternContext {
   121→	return &PatternContext{
   122→		Program:        program,
   123→		VariableUsage:  make(map[string]int),
   124→		LoopInvariants: make(map[string]bool),
   125→		RepeatedExprs:  make(map[string]int),
   126→		FunctionCalls:  make(map[string]int),
   127→		AssignedVars:   make(map[string]bool),
   128→		ReadVars:       make(map[string]bool),
   129→	}
   130→}
   131→
   132→// AnalyzeNode recursively analyzes a node for patterns
   133→func (pc *PatternContext) AnalyzeNode(node *ast.Node) {
   134→	if node == nil {
   135→		return
   136→	}
   137→
   138→	switch node.Kind {
   139→	case ast.NodeLetDecl:
   140→		if len(node.Children) > 0 {
   141→			varName := node.Children[0].Value
   142→			pc.AssignedVars[varName] = true
   143→		}
   144→		for _, child := range node.Children {
   145→			pc.AnalyzeNode(child)
   146→		}
   147→
   148→	case ast.NodeIdent:
   149→		pc.VariableUsage[node.Value]++
   150→		pc.ReadVars[node.Value] = true
   151→
   152→	case ast.NodeBinaryExpr:
   153→		sig := PatternSignature(node)
   154→		pc.RepeatedExprs[sig]++
   155→		for _, child := range node.Children {
   156→			pc.AnalyzeNode(child)
   157→		}
   158→
   159→	case ast.NodeCallExpr:
   160→		pc.FunctionCalls[node.Value]++
   161→		for _, child := range node.Children {
   162→			pc.AnalyzeNode(child)
   163→		}
   164→
   165→	case ast.NodeForStmt:
   166→		oldInLoop := pc.InLoop
   167→		pc.InLoop = true
   168→		for _, child := range node.Children {
   169→			pc.AnalyzeNode(child)
   170→		}
   171→		pc.InLoop = oldInLoop
   172→
   173→	default:
   174→		for _, child := range node.Children {
   175→			pc.AnalyzeNode(child)
   176→		}
   177→	}
   178→}
   179→
   180→// DetectDeadAssigns finds variables assigned but never read
   181→func (pc *PatternContext) DetectDeadAssigns() []string {
   182→	var deadAssigns []string
   183→	for varName := range pc.AssignedVars {
   184→		if !pc.ReadVars[varName] {
   185→			deadAssigns = append(deadAssigns, varName)
   186→		}
   187→	}
   188→	return deadAssigns
   189→}
   190→
   191→// findFunctionDef searches for a function definition by name
   192→func findFunctionDef(fnName string, program *ast.Node) (*ast.Node, bool) {
   193→	if program == nil || program.Kind != ast.NodeProgram {
   194→		return nil, false
   195→	}
   196→	for _, stmt := range program.Children {
   197→		if stmt.Kind == ast.NodeFnDecl && stmt.Value == fnName {
   198→			return stmt, true
   199→		}
   200→	}
   201→	return nil, false
   202→}
   203→
   204→// nodeKindStr converts NodeKind to string for signature generation
   205→func nodeKindStr(kind ast.NodeKind) string {
   206→	switch kind {
   207→	case ast.NodeProgram:
   208→		return "Program"
   209→	case ast.NodeLetDecl:
   210→		return "LetDecl"
   211→	case ast.NodeFnDecl:
   212→		return "FnDecl"
   213→	case ast.NodeIfStmt:
   214→		return "IfStmt"
   215→	case ast.NodeForStmt:
   216→		return "ForStmt"
   217→	case ast.NodeBinaryExpr:
   218→		return "BinaryExpr"
   219→	case ast.NodeCallExpr:
   220→		return "CallExpr"
   221→	case ast.NodeIdent:
   222→		return "Ident"
   223→	case ast.NodeIntLit:
   224→		return "IntLit"
   225→	case ast.NodeReturn:
   226→		return "Return"
   227→	case ast.NodeBlockStmt:
   228→		return "BlockStmt"
   229→	default:
   230→		return "Unknown"
   231→	}
   232→}
   233→
   234→// SignaturePattern is a pattern with its count per build
   235→type SignaturePattern struct {
   236→	Signature string
   237→	Kind      PatternKind
   238→	Count     int64
   239→	SavedNs   int64
   240→}
   241→
   242→// TopPatterns returns the top N most frequent patterns
   243→func (pc *PatternContext) TopPatterns(n int) []SignaturePattern {
   244→	patterns := make([]SignaturePattern, 0)
   245→
   246→	// Collect repeated expressions
   247→	for sig, count := range pc.RepeatedExprs {
   248→		if count > 1 {
   249→			patterns = append(patterns, SignaturePattern{
   250→				Signature: sig,
   251→				Kind:      PatternRepeatedSubExpr,
   252→				Count:     int64(count),
   253→				SavedNs:   0,
   254→			})
   255→		}
   256→	}
   257→
   258→	// Collect function calls
   259→	for fnName, count := range pc.FunctionCalls {
   260→		patterns = append(patterns, SignaturePattern{
   261→			Signature: "CallExpr:" + fnName,
   262→			Kind:      PatternInlinableCall,
   263→			Count:     int64(count),
   264→			SavedNs:   0,
   265→		})
   266→	}
   267→
   268→	// Sort by count (simple bubble sort for small N)
   269→	for i := 0; i < len(patterns)-1; i++ {
   270→		for j := i + 1; j < len(patterns); j++ {
   271→			if patterns[j].Count > patterns[i].Count {
   272→				patterns[i], patterns[j] = patterns[j], patterns[i]
   273→			}
   274→		}
   275→	}
   276→
   277→	// Return top N
   278→	if n > len(patterns) {
   279→		n = len(patterns)
   280→	}
   281→	return patterns[:n]
   282→}
   283→
   284→// FindConstantExprs finds all binary expressions with constant operands
   285→func (pc *PatternContext) FindConstantExprs(node *ast.Node) []SignaturePattern {
   286→	var patterns []SignaturePattern
   287→	findConstExpr(node, &patterns)
   288→	return patterns
   289→}
   290→
   291→func findConstExpr(node *ast.Node, patterns *[]SignaturePattern) {
   292→	if node == nil {
   293→		return
   294→	}
   295→
   296→	if node.Kind == ast.NodeBinaryExpr && len(node.Children) == 2 {
   297→		if isLiteral(node.Children[0]) && isLiteral(node.Children[1]) {
   298→			sig := PatternSignature(node)
   299→			*patterns = append(*patterns, SignaturePattern{
   300→				Signature: sig,
   301→				Kind:      PatternConstantExpr,
   302→				Count:     1,
   303→				SavedNs:   0,
   304→			})
   305→		}
   306→	}
   307→
   308→	for _, child := range node.Children {
   309→		findConstExpr(child, patterns)
   310→	}
   311→}
   312→

