     1→// Package profiler implements pattern database persistence
     2→package profiler
     3→
     4→import (
     5→	"crypto/sha256"
     6→	"encoding/json"
     7→	"fmt"
     8→	"io/ioutil"
     9→	"os"
    10→	"time"
    11→)
    12→
    13→// BuildRecord stores metrics from a single build execution
    14→type BuildRecord struct {
    15→	ID         string    `json:"id"`
    16→	Timestamp  time.Time `json:"timestamp"`
    17→	SourceHash string    `json:"source_hash"`
    18→	BuildTimeNs int64    `json:"build_time_ns"`
    19→	PatternsHit []string `json:"patterns_hit"`
    20→	OutputSize int      `json:"output_size"`
    21→}
    22→
    23→// PatternEntry is persisted pattern data
    24→type PatternEntry struct {
    25→	Kind      string `json:"kind"`
    26→	Signature string `json:"signature"`
    27→	Count     int64  `json:"count"`
    28→	SavedNs   int64  `json:"saved_ns"`
    29→}
    30→
    31→// Database stores patterns and build history
    32→type Database struct {
    33→	Patterns     []PatternEntry `json:"patterns"`
    34→	TotalBuilds  int            `json:"total_builds"`
    35→	LastUpdated  time.Time      `json:"last_updated"`
    36→	BuildHistory []BuildRecord  `json:"build_history"`
    37→}
    38→
    39→// NewDatabase creates an empty database
    40→func NewDatabase() *Database {
    41→	return &Database{
    42→		Patterns:     []PatternEntry{},
    43→		BuildHistory: []BuildRecord{},
    44→		LastUpdated:  time.Now(),
    45→	}
    46→}
    47→
    48→// LoadFromFile loads database from JSON file
    49→func LoadFromFile(path string) (*Database, error) {
    50→	data, err := ioutil.ReadFile(path)
    51→	if err != nil {
    52→		if os.IsNotExist(err) {
    53→			return NewDatabase(), nil
    54→		}
    55→		return nil, err
    56→	}
    57→
    58→	var db Database
    59→	if err := json.Unmarshal(data, &db); err != nil {
    60→		return nil, err
    61→	}
    62→	return &db, nil
    63→}
    64→
    65→// SaveToFile persists database to JSON file
    66→func (db *Database) SaveToFile(path string) error {
    67→	data, err := json.MarshalIndent(db, "", "  ")
    68→	if err != nil {
    69→		return err
    70→	}
    71→	return ioutil.WriteFile(path, data, 0644)
    72→}
    73→
    74→// UpdateFromCollector merges collector results into database
    75→func (db *Database) UpdateFromCollector(collector *Collector, sourceCode string) {
    76→	// Create unique ID for this build
    77→	buildID := fmt.Sprintf("build_%d", db.TotalBuilds+1)
    78→
    79→	// Calculate source hash
    80→	hash := sha256.Sum256([]byte(sourceCode))
    81→	sourceHash := fmt.Sprintf("%x", hash)
    82→
    83→	// Create build record
    84→	record := BuildRecord{
    85→		ID:          buildID,
    86→		Timestamp:   time.Now(),
    87→		SourceHash:  sourceHash,
    88→		BuildTimeNs: collector.GetBuildTimeNs(),
    89→		PatternsHit: []string{},
    90→		OutputSize:  0,
    91→	}
    92→
    93→	// Update patterns
    94→	newPatterns := collector.GetPatterns()
    95→	for _, newP := range newPatterns {
    96→		found := false
    97→		for i, existing := range db.Patterns {
    98→			if existing.Signature == newP.Signature {
    99→				db.Patterns[i].Count += newP.Count
   100→				db.Patterns[i].SavedNs += newP.SavedNs
   101→				record.PatternsHit = append(record.PatternsHit, newP.Signature)
   102→				found = true
   103→				break
   104→			}
   105→		}
   106→
   107→		if !found {
   108→			db.Patterns = append(db.Patterns, PatternEntry{
   109→				Kind:      newP.Kind.String(),
   110→				Signature: newP.Signature,
   111→				Count:     newP.Count,
   112→				SavedNs:   newP.SavedNs,
   113→			})
   114→			record.PatternsHit = append(record.PatternsHit, newP.Signature)
   115→		}
   116→	}
   117→
   118→	// Update metadata
   119→	db.TotalBuilds++
   120→	db.LastUpdated = time.Now()
   121→	db.BuildHistory = append(db.BuildHistory, record)
   122→
   123→	// Keep only last 100 builds to avoid unbounded growth
   124→	if len(db.BuildHistory) > 100 {
   125→		db.BuildHistory = db.BuildHistory[len(db.BuildHistory)-100:]
   126→	}
   127→}
   128→
   129→// TopPatterns returns the top N patterns by frequency
   130→func (db *Database) TopPatterns(n int) []PatternEntry {
   131→	patterns := make([]PatternEntry, len(db.Patterns))
   132→	copy(patterns, db.Patterns)
   133→
   134→	// Sort by count descending
   135→	for i := 0; i < len(patterns)-1; i++ {
   136→		for j := i + 1; j < len(patterns); j++ {
   137→			if patterns[j].Count > patterns[i].Count {
   138→				patterns[i], patterns[j] = patterns[j], patterns[i]
   139→			}
   140→		}
   141→	}
   142→
   143→	if n > len(patterns) {
   144→		n = len(patterns)
   145→	}
   146→	return patterns[:n]
   147→}
   148→
   149→// AverageBuildTime returns the average build time in nanoseconds
   150→func (db *Database) AverageBuildTime() int64 {
   151→	if len(db.BuildHistory) == 0 {
   152→		return 0
   153→	}
   154→
   155→	total := int64(0)
   156→	for _, record := range db.BuildHistory {
   157→		total += record.BuildTimeNs
   158→	}
   159→	return total / int64(len(db.BuildHistory))
   160→}
   161→
   162→// LatestBuildTime returns the most recent build time
   163→func (db *Database) LatestBuildTime() int64 {
   164→	if len(db.BuildHistory) == 0 {
   165→		return 0
   166→	}
   167→	return db.BuildHistory[len(db.BuildHistory)-1].BuildTimeNs
   168→}
   169→
   170→// DetectRegression detects if latest build is significantly slower than average
   171→func (db *Database) DetectRegression(threshold float64) (bool, float64) {
   172→	if len(db.BuildHistory) < 5 {
   173→		return false, 0
   174→	}
   175→
   176→	avg := db.AverageBuildTime()
   177→	latest := db.LatestBuildTime()
   178→
   179→	if avg == 0 {
   180→		return false, 0
   181→	}
   182→
   183→	ratio := float64(latest) / float64(avg)
   184→	if ratio > threshold {
   185→		return true, ratio
   186→	}
   187→	return false, ratio
   188→}
   189→
   190→// GetPatternStats returns detailed statistics for a specific pattern
   191→func (db *Database) GetPatternStats(signature string) (PatternEntry, bool) {
   192→	for _, p := range db.Patterns {
   193→		if p.Signature == signature {
   194→			return p, true
   195→		}
   196→	}
   197→	return PatternEntry{}, false
   198→}
   199→
   200→// Summary returns a human-readable summary of database state
   201→func (db *Database) Summary() string {
   202→	return fmt.Sprintf("Database: %d patterns learned, %d builds recorded, last updated %s",
   203→		len(db.Patterns),
   204→		db.TotalBuilds,
   205→		db.LastUpdated.Format(time.RFC3339))
   206→}
   207→

