     9→func TestParseLetDecl(t *testing.T) {
    10→	tests := []struct {
    11→		input  string
    12→		varName string
    13→		wantErr bool
    14→	}{
    15→		{"let x = 10", "x", false},
    16→		{"let y = 20", "y", false},
    17→		{"let abc = 100 + 200", "abc", false},
    18→	}
    19→
    20→	for _, tt := range tests {
    21→		p := New(tt.input)
    22→		prog, err := p.ParseProgram()
    23→		if (err != nil) != tt.wantErr {
    24→			t.Errorf("Input %q: error = %v, wantErr %v", tt.input, err, tt.wantErr)
    25→			continue
    26→		}
    27→		if err != nil {
    28→			continue
    29→		}
    30→		if len(prog.Children) != 1 {
    31→			t.Errorf("Input %q: expected 1 statement, got %d", tt.input, len(prog.Children))
    32→			continue
    33→		}
    34→		stmt := prog.Children[0]
    35→		if stmt.Kind != ast.NodeLetDecl {
    36→			t.Errorf("Input %q: expected NodeLetDecl, got %v", tt.input, stmt.Kind)
    37→			continue
    38→		}
    39→		if len(stmt.Children) < 1 || stmt.Children[0].Value != tt.varName {
    40→			t.Errorf("Input %q: expected var name %q, got %q", tt.input, tt.varName,
    41→				func() string {
    42→					if len(stmt.Children) > 0 {
    43→						return stmt.Children[0].Value
    44→					}
    45→					return ""
    46→				}())
    47→		}
    48→	}
    49→}
